import CoreML
import XCTest
import simd
import ShuttlCore
import ShuttlRally

/// Parity tests for the learned stroke classifier: the Swift feature builder and the on-device
/// CoreML model against the research pipeline that measured the accuracy.
///
/// The fixture in `Fixtures/bststroke/` was generated by
/// `Fixtures/bststroke/generate_fixture.py` from `research/extract/out/039.npz` +
/// `research/rtmpose/pose/039.npz`. It self-checks before writing: for every clip it stores, the
/// arrays it computed are compared against the `*_joints/pos/shuttle.npy` that
/// `e2e_convert.py --arm fixed --shift 2` wrote for the same clip, so these expectations are the
/// measurement's, not a re-implementation's. The logits are the repo's own forward
/// (model.bst.BST_CG_AP) on the 10 released checkpoints, averaged — the PyTorch reference the
/// CoreML model was verified against (749 match-039 clips: max |logit - PyTorch| 2.4e-6, 100 %
/// argmax agreement, accuracy 0.8264).
///
/// What each assertion catches:
///   - expected_frames / expected_window: the +2-frame detector lead as TIME, and the seq30 window
///     at 25/30/60 fps. A rule that used frames instead of seconds fails at 60 fps only.
///   - expected_joints / pos / shuttle: the box normalisation, the far/near slot order, the
///     "both players resolved" gate, the court-position mapping and the end padding.
///   - expected_logits / expected_argmax: the class order, the bone computation, the mask, and the
///     CoreML conversion itself.
final class StrokeClassifierParityTests: XCTestCase {

    /// The CoreML model agrees with PyTorch to 2.4e-6, so 1e-3 is far above the conversion's own
    /// noise and far below any real mistake (a wrong input order shifts logits by ~1).
    private static let logitTolerance: Float = 1e-3

    private static var fixtureDir: URL {
        URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("Fixtures/bststroke")
    }
    /// research/bst/coreml: the .mlpackage the CoreML numbers in the report come from.
    private static var repoModelURL: URL {
        Self.fixtureDir.deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("research/bst/coreml/BSTStroke.mlpackage")
    }

    // MARK: Fixture

    struct Fixture: Decodable {
        struct Frame: Decodable {
            struct Player: Decodable {
                var box: [Double]?
                /// 17 rows of [x, y, conf]; x/y null when the keypoint is not finite.
                var kp: [[Double?]]
                var foot: [Double]?
            }
            var frames: [Int]
            var far: [Player]
            var near: [Player]
            /// x/W, y/H of the shuttle; null when the tracker had no position (NaN).
            var shuttle_xy: [[Double?]]
            var shuttle_visible: [Bool]
            var width: Int
            var height: Int
        }
        struct Case: Decodable {
            var name: String
            var hit_frame: Int
            var fps: Double
            var n_frames: Int
            var expected_window: [Int]
            var expected_frames: [Int]
            var resolved_frames: Int
            var label: String
            var inputs: Frame
            var expected_joints: String
            var expected_pos: String
            var expected_shuttle: String
            var expected_logits: String
            var expected_argmax: Int
        }
        struct WindowCase: Decodable {
            var hit_frame: Int
            var fps: Double
            var n_frames: Int
            var expected: [Int]?
        }
        var fps: Double
        var width: Int
        var height: Int
        var hit_lead_seconds: Double
        var classes: [String]
        var checked_against_e2e: Int
        var clip_cases: [Case]
        var pad_cases: [Case]
        var window_cases: [WindowCase]
    }

    private func loadFixture() throws -> Fixture {
        let url = Self.fixtureDir.appendingPathComponent("parity.json")
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw XCTSkip("fixture missing at \(url.path) — run generate_fixture.py")
        }
        return try JSONDecoder().decode(Fixture.self, from: try Data(contentsOf: url))
    }

    private static func floats(_ b64: String) -> [Float] {
        guard let d = Data(base64Encoded: b64) else { return [] }
        return d.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
    }

    /// The app's own types, out of the fixture's per-frame inputs.
    private static func build(_ f: Fixture.Frame) -> (meta: VideoMeta, players: [PlayerObservation], track: Track2D) {
        var players: [PlayerObservation] = []
        var xy: [SIMD2<Double>] = [], visible: [Bool] = [], conf: [Double] = [], interpolated: [Bool] = []
        for (i, frame) in f.frames.enumerated() {
            for (side, list) in [(CourtSide.far, f.far), (CourtSide.near, f.near)] {
                let p = list[i]
                let kp = p.kp.map { row in
                    Keypoint(x: row[0] ?? .nan, y: row[1] ?? .nan, conf: row[2] ?? 0)
                }
                players.append(PlayerObservation(frame: frame, trackID: side == .far ? 2 : 1,
                                                 bbox: BBox(x1: p.box?[0] ?? .nan, y1: p.box?[1] ?? .nan,
                                                            x2: p.box?[2] ?? .nan, y2: p.box?[3] ?? .nan),
                                                 score: 1, side: side,
                                                 footWorld: p.foot.map { SIMD2($0[0], $0[1]) },
                                                 keypoints: kp))
            }
            xy.append(SIMD2(f.shuttle_xy[i][0] ?? .nan, f.shuttle_xy[i][1] ?? .nan))
            visible.append(f.shuttle_visible[i])
            conf.append(0)
            interpolated.append(false)
        }
        // the fixture holds contiguous frames; the track is indexed by frame number
        let last = f.frames.last ?? 0
        let n = last + 1
        var t = [Double](repeating: 0, count: n), txy = [SIMD2<Double>](repeating: SIMD2(.nan, .nan), count: n)
        var vis = [Bool](repeating: false, count: n), ic = [Double](repeating: 0, count: n)
        var interp = [Bool](repeating: false, count: n)
        for (i, frame) in f.frames.enumerated() {
            t[frame] = Double(frame) / 30
            txy[frame] = xy[i]; vis[frame] = visible[i]
        }
        let meta = VideoMeta(fps: 30, width: f.width, height: f.height, nFrames: n, timestamps: t)
        return (meta, players, Track2D(t: t, xy: txy, conf: ic, visible: vis, interpolated: interp))
    }

    private func assertCase(_ c: Fixture.Case, _ model: BSTStrokeModel?) throws {
        let (meta, players, track) = Self.build(c.inputs)
        let index = PlayerFrameIndex(players)

        // 1. the window rule (source frames; the reference stores the whole inclusive window).
        // The video_end case ends the video inside the window on purpose: its expected window is
        // the one cut at the video's last frame.
        guard let w = StrokeFeatures.windowFrames(hitFrame: c.hit_frame, fps: c.fps, nFrames: c.n_frames) else {
            return XCTFail("\(c.name): no window")
        }
        XCTAssertEqual(w.window, c.expected_window, "\(c.name): source window")
        XCTAssertEqual(w.used, c.expected_frames.count, "\(c.name): frames used")

        // 2. the feature arrays
        guard let clip = StrokeFeatures.clip(hitFrame: c.hit_frame, meta: meta, players: index, track: track) else {
            return XCTFail("\(c.name): no clip")
        }
        XCTAssertEqual(clip.frames, c.expected_frames, "\(c.name): clip frames")
        XCTAssertEqual(clip.videoLen, c.expected_frames.count, "\(c.name): videoLen")
        XCTAssertEqual(clip.resolvedFrames, c.resolved_frames, "\(c.name): resolved frames")

        let ej = Self.floats(c.expected_joints), ep = Self.floats(c.expected_pos), es = Self.floats(c.expected_shuttle)
        // the reference arrays cover the whole window; compare the first videoLen slots
        let n = clip.videoLen
        // (the clip itself is always 30 slots; the real frames come first, then the padding)
        XCTAssertEqual(Array(clip.joints.prefix(n * 68)), Array(ej.prefix(n * 68)), "\(c.name): joints")
        XCTAssertEqual(Array(clip.pos.prefix(n * 4)), Array(ep.prefix(n * 4)), "\(c.name): pos")
        XCTAssertEqual(Array(clip.shuttle.prefix(n * 2)), Array(es.prefix(n * 2)), "\(c.name): shuttle")
        XCTAssertEqual(clip.joints.count, 30 * 68)
        // and the padding really is zero
        XCTAssertTrue(clip.joints[(n * 68)...].allSatisfy { $0 == 0 }, "\(c.name): joints padding")
        XCTAssertTrue(clip.pos[(n * 4)...].allSatisfy { $0 == 0 }, "\(c.name): pos padding")
        XCTAssertTrue(clip.shuttle[(n * 2)...].allSatisfy { $0 == 0 }, "\(c.name): shuttle padding")
        XCTAssertTrue(clip.valid.enumerated().allSatisfy { $0.offset < n ? $0.element == 1 : $0.element == 0 },
                      "\(c.name): valid mask")

        // 3. the model
        guard let model else { return }          // feature-builder-only run: nothing more to assert
        let logits = try model.logits(clip)
        let expected = Self.floats(c.expected_logits)
        XCTAssertEqual(logits.count, expected.count)
        let worst = zip(logits, expected).map { abs($0 - $1) }.max() ?? 0
        XCTAssertLessThan(worst, Self.logitTolerance, "\(c.name): max |logit - PyTorch| \(worst)")
        XCTAssertEqual(logits.firstIndex(of: logits.max()!), c.expected_argmax, "\(c.name): argmax")
    }

    // MARK: Model loading

    /// The package resource (compiled once into a scratch directory that survives the test run),
    /// or the repo's .mlpackage. nil when no model is available anywhere (the tests then assert the
    /// feature builder only).
    private static let cacheDirectory = URL(fileURLWithPath: NSTemporaryDirectory())
        .appendingPathComponent("bststroke-test-cache")

    private func model() async throws -> BSTStrokeModel? {
        if let m = Self.sharedModel { return m }
        for url in [BSTStrokeModel.bundledModelURL(), Self.repoModelURL].compactMap({ $0 }) {
            if let m = BSTStrokeModel.loadCached(modelURL: url, cacheDirectory: Self.cacheDirectory) { return m }
            if let m = await BSTStrokeModel.compileAndLoad(modelURL: url, cacheDirectory: Self.cacheDirectory) { return m }
        }
        throw XCTSkip("no BSTStroke model available (bundle or \(Self.repoModelURL.path))")
    }

    /// The already-compiled model when the cache holds one (so the common case stays synchronous).
    private static let sharedModel: BSTStrokeModel? = {
        for url in [BSTStrokeModel.bundledModelURL(), repoModelURL].compactMap({ $0 }) {
            if let m = BSTStrokeModel.loadCached(modelURL: url, cacheDirectory: cacheDirectory) { return m }
        }
        return nil
    }()

    // MARK: Tests

    func testWindowRuleMatchesTheResearchPipeline() throws {
        let f = try loadFixture()
        for c in f.window_cases {
            switch StrokeFeatures.windowFrames(hitFrame: c.hit_frame, fps: c.fps, nFrames: c.n_frames) {
            case nil:
                XCTAssertNil(c.expected, "hit \(c.hit_frame) @ \(c.fps) fps should have a window")
            case let w?:
                XCTAssertEqual(w.window, c.expected ?? [], "hit \(c.hit_frame) @ \(c.fps) fps")
            }
        }
        XCTAssertEqual(StrokeFeatures.hitLeadSeconds, 2.0 / 30.0, accuracy: 1e-12)
    }

    func testFeatureBuilderMatchesConvertPy() throws {
        let f = try loadFixture()
        XCTAssertGreaterThanOrEqual(f.checked_against_e2e, 1, "fixture was not cross-checked")
        for c in f.clip_cases + f.pad_cases { try assertCase(c, nil) }
    }

    func testModelMatchesPyTorchLogits() async throws {
        let f = try loadFixture()
        guard let m = try await model() else { return XCTFail("no CoreML model") }
        for c in f.clip_cases + f.pad_cases { try assertCase(c, m) }
    }

    func testClassListAndMapping() throws {
        let f = try loadFixture()
        XCTAssertEqual(f.classes, StrokeClasses.names, "fixture class order vs the Swift class list")
        XCTAssertEqual(f.classes.count, 25)
        // 0 is the abstain class; 1...12 far/Top, 13...24 near/Bottom, in the model's own order
        XCTAssertNil(StrokeClasses.decode(0))
        XCTAssertEqual(StrokeClasses.decode(1)?.striker, .far)
        XCTAssertEqual(StrokeClasses.decode(12)?.striker, .far)
        XCTAssertEqual(StrokeClasses.decode(13)?.striker, .near)
        XCTAssertEqual(StrokeClasses.decode(24)?.striker, .near)
        XCTAssertEqual(StrokeClasses.decode(1)?.type.rawValue,
                       StrokeClasses.decode(13)?.type.rawValue, "两边共用同一张类型表")
        XCTAssertEqual(StrokeClasses.decode(24)?.type.rawValue,
                       StrokeClasses.decode(12)?.type.rawValue, "第 13~24 类与第 1~12 类一一对应")
        XCTAssertEqual(StrokeClasses.decode(12)?.type.rawValue, "long_serve")
        XCTAssertNotEqual(StrokeClasses.decode(1)?.striker, StrokeClasses.decode(13)?.striker,
                          "Top 与 Bottom 是不同的击球方")
        XCTAssertNil(StrokeClasses.decode(25))
        // every class maps to a type the app can carry
        for i in 1...24 { XCTAssertNotNil(StrokeClasses.decode(i)?.type) }
    }

    /// The model's verdict replaces the rules' when it can rule, and never touches a rally it
    /// cannot build a clip for.
    func testRefineReplacesTypesButKeepsTheRallyIntact() async throws {
        let f = try loadFixture()
        let m = try await model()
        guard let m else { return XCTFail("no CoreML model") }
        StrokeClassifier.install(m, pinned: true)
        defer { StrokeClassifier.install(nil, pinned: true) }
        // a clip whose class is neither an abstention nor a serve kind (the rally's first hit
        // keeps its type, so the refine path can only be observed on a later shot)
        guard let case0 = f.clip_cases.first(where: {
            guard let d = StrokeClasses.decode($0.expected_argmax) else { return false }
            return d.type != .shortServe && d.type != .longServe
        }) else { return XCTFail("the fixture has no classful clip") }
        let (meta, players, track) = Self.build(case0.inputs)
        let frame = case0.expected_frames[case0.expected_frames.count / 2]
        // A rally whose measured shot is the second one: the first is a serve, so the rules do
        // their serve branch and the model still gets to rule on the shot under test.
        let hit = HitEvent(frame: case0.hit_frame, t: Double(case0.hit_frame) / 30,
                           xyPx: SIMD2(640, 300), hitter: .near, confidence: 0.9, playerTrackID: 1)
        // The rally's first hit is a serve by definition; it sits one second before the shot
        // under test and inside the same tracked stretch, so both clips are usable.
        let serveFrame = case0.expected_frames[0] + 10
        let serveHit = HitEvent(frame: serveFrame, t: Double(serveFrame) / 30,
                                xyPx: SIMD2(640, 300), hitter: .far, confidence: 0.9, playerTrackID: 2)
        let rally = RallyV2(startFrame: 0, endFrame: frame, shots: [
            ShotEventV2(hit: serveHit, segment: nil, shotType: .serve, shotTypeConfidence: 0.3),
            ShotEventV2(hit: hit, segment: nil, shotType: .drive, shotTypeConfidence: 0.3,
                        hitterPosWorld: SIMD2(-1, 0), hitHeightM: 1.2, strokeSide: .forehand),
        ])
        let base = ShotClassifier.classifyShots(rally, camera: nil, players: players, learned: false)
        // The model never runs here (nothing installed), so the rally is the untouched rules'
        // verdict; only the hit near the fixture's window must be the one the model can re-rule.
        XCTAssertEqual(base.shots.count, 2)
        XCTAssertEqual(base.shots[0].shotType, .serve, "规则把第一球判成发球")
        let shotIndex = base.shots.firstIndex { $0.hit.frame == case0.hit_frame } ?? -1
        XCTAssertEqual(shotIndex, 1, "两球按帧序排列")
        let refined = StrokeClassifier.refine(base, meta: meta, track: track, players: players)
        guard let expected = StrokeClasses.decode(case0.expected_argmax) else {
            return XCTFail("\(case0.name): the model abstained, the fixture needs a classful clip")
        }
        XCTAssertNotEqual(expected.type, .shortServe, "the classful clip must not be a serve kind")
        XCTAssertEqual(refined.shots[1].shotType, expected.type)
        XCTAssertEqual(refined.shots[1].hit.hitter, expected.striker)
        XCTAssertGreaterThan(refined.shots[1].shotTypeConfidence, 0)
        // Both hits have a usable clip and both get the model's verdict; which class the serve's
        // clip reads as is a property of that clip, not of the switch.
        XCTAssertEqual((StrokeClassifier.lastDiagnostics?.refined ?? 0)
                       + (StrokeClassifier.lastDiagnostics?.kept ?? 0), 2)
        XCTAssertEqual(StrokeClassifier.lastDiagnostics?.unusable, 0)
        // no meta / no track / no players: untouched
        XCTAssertEqual(StrokeClassifier.refine(base, meta: nil, track: track, players: players).shots[1].shotType,
                       base.shots[1].shotType)
        XCTAssertEqual(StrokeClassifier.refine(base, meta: meta, track: track, players: []).shots[1].shotType,
                       base.shots[1].shotType)
        // a hit far outside the fixture's tracked stretch has no usable clip: the rules keep it
        let farShot = HitEvent(frame: 5000, t: 100, xyPx: SIMD2(1, 1), hitter: .near, confidence: 0.9)
        let farRally = RallyV2(startFrame: 0, endFrame: 6000, shots: [
            ShotEventV2(hit: serveHit, segment: nil, shotType: .serve, shotTypeConfidence: 0.3),
            ShotEventV2(hit: hit, segment: nil, shotType: .drive, shotTypeConfidence: 0.3),
            ShotEventV2(hit: farShot, segment: nil, shotType: .drive, shotTypeConfidence: 0.3),
        ])
        let farOut = StrokeClassifier.refine(farRally, meta: meta, track: track, players: players)
        XCTAssertEqual(farOut.shots[2].shotType, .drive, "没有球员姿态的那一球保持规则判定")
        // exactly the far shot is unusable; the serve is kept only if its clip read as a non-serve
        // class (a property of that clip, not of the switch), so `kept` is unusable + unsure.
        XCTAssertEqual(StrokeClassifier.lastDiagnostics?.unusable, 1)
        XCTAssertEqual(StrokeClassifier.lastDiagnostics?.kept,
                       (StrokeClassifier.lastDiagnostics?.unusable ?? -1) + (StrokeClassifier.lastDiagnostics?.unsure ?? -1))
        // everything else about the shot survives
        XCTAssertEqual(refined.shots[1].hit.frame, base.shots[1].hit.frame)
        XCTAssertEqual(refined.shots[1].hitterPosWorld, base.shots[1].hitterPosWorld)
        XCTAssertEqual(refined.shots[1].hitHeightM, base.shots[1].hitHeightM)
    }

    /// The fallback: with the model unavailable, `classifyShots` is exactly the rule-based port,
    /// and the pipeline's extra meta / track arguments change nothing.
    func testRuleBasedFallbackIsUnchangedWithoutTheModel() throws {
        let f = try loadFixture()
        let case0 = f.clip_cases[0]
        let (meta, players, track) = Self.build(case0.inputs)
        let hit = HitEvent(frame: case0.hit_frame, t: Double(case0.hit_frame) / 30, xyPx: SIMD2(640, 300),
                           hitter: .near, confidence: 0.9, playerTrackID: 1)
        let rally = RallyV2(startFrame: 0, endFrame: 0, shots: [ShotEventV2(hit: hit, segment: nil)])
        XCTAssertNil(StrokeClassifier.model, "another test pinned a model")
        let a = ShotClassifier.classifyShots(rally, camera: nil, players: players, meta: meta, track: track)
        let b = ShotClassifier.classifyShots(rally, camera: nil, players: players, learned: false)
        XCTAssertEqual(a.shots.map(\.shotType), b.shots.map(\.shotType))
        XCTAssertNil(StrokeClassifier.lastDiagnostics, "no model -> no diagnostics")
    }

    /// The installed model is what `classifyShots` uses by default (the app's path), and it is
    /// what the diagnostic says it used. Restores the no-model state for the other tests.
    func testInstalledModelIsUsedByDefault() async throws {
        let f = try loadFixture()
        guard let m = try await model() else { return XCTFail("no CoreML model") }
        let case0 = f.clip_cases[0]
        guard let expected = StrokeClasses.decode(case0.expected_argmax) else {
            return XCTFail("\(case0.name): the model abstained")
        }
        let (meta, players, track) = Self.build(case0.inputs)
        let hit = HitEvent(frame: case0.hit_frame, t: Double(case0.hit_frame) / 30, xyPx: SIMD2(640, 300),
                           hitter: .far, confidence: 0.9, playerTrackID: 2)
        let rally = RallyV2(startFrame: 0, endFrame: 0, shots: [ShotEventV2(hit: hit, segment: nil)])
        StrokeClassifier.install(m, pinned: true)
        defer { StrokeClassifier.install(nil, pinned: true) }
        let out = ShotClassifier.classifyShots(rally, camera: nil, players: players, meta: meta, track: track)
        XCTAssertEqual(out.shots[0].shotType, expected.type)
        XCTAssertEqual(StrokeClassifier.lastDiagnostics?.model, "BSTStroke")
        XCTAssertEqual(StrokeClassifier.lastDiagnostics?.shots, 1)
    }
}
